scripts.factorial_mod:
def solve(inputs: dict) -> float:
    N = inputs['N']
    MOD = inputs['MOD']

    result = 1
    for i in range(1, N + 1):
        result = (result * i) % MOD

    return float(result)

scripts.gcd_list:
from math import gcd
from functools import reduce

def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    result = reduce(gcd, values)
    return float(result)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    count = 0

    # Count all pairs (i, j) where i < j and values[i] > values[j]
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.sum_floor_division:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    total = 0
    for i in range(len(A)):
        total += A[i] // B[i]

    return float(total)

